import { runScript } from '/app/sdk/runner';

await runScript(async (ctx) => {
    const { bot, sdk } = ctx;
    await bot.skipTutorial();

    console.log('[CookingBot] Started training loop...');

    while (true) {
        await bot.dismissBlockingUI();
        const state = sdk.getState();

